import React from 'react';

function TestApp() {
  return (
    <div style={{ 
      textAlign: 'center', 
      marginTop: '100px',
      fontFamily: 'Arial, sans-serif'
    }}>
      <h1>React Test Page</h1>
      <p>If you can see this, React is working correctly!</p>
      <button 
        style={{
          padding: '10px 20px',
          backgroundColor: '#4CAF50',
          color: 'white',
          border: 'none',
          borderRadius: '4px',
          cursor: 'pointer'
        }}
        onClick={() => alert('Button clicked!')}
      >
        Click Me
      </button>
    </div>
  );
}

export default TestApp;
